function L({registerIndicator:w,sourceValues:N,nulls:d}){const F=(c,i)=>{const u=Math.abs(c);return u>i?Math.sign(c)*(u-i):0};w({id:"oa-wavelet",name:"Wavelet Denoising Filter (WAVELET)",category:"Filters",placement:"onchart",inputs:[{key:"levels",type:"number",label:"Decomposition Levels",default:4,min:1,max:8,step:1,tooltip:"Number of wavelet decomposition levels. Each level doubles the effective smoothing window. Lookback = 2^levels bars."},{key:"threshold",type:"number",label:"Threshold Multiplier",default:1,min:0,max:5,step:.1,tooltip:"Scales the universal noise threshold. 0 = no denoising (passthrough). Higher = more aggressive smoothing."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"wavelet",type:"line",title:"Wavelet",style:{color:"#ffeb3b",lineWidth:2}}],calc(c,i){const u=Math.floor(Number(i.levels)||4),f=Math.min(8,Math.max(1,u)),k=Math.min(5,Math.max(0,Number(i.threshold)||0)),h=N(c,i.source??"close"),l=c.length,b=new Array(l).fill(NaN);if(l===0)return{wavelet:d(b)};const s=[new Array(l).fill(0)];for(let e=1;e<=8;e++)s.push(new Array(l).fill(0));const n=[];for(let e=0;e<=8;e++)n.push(new Array(l).fill(0));for(let e=0;e<l;e++){const a=Number.isFinite(h[e])?h[e]:0;s[0][e]=a;const M=e>=1&&Number.isFinite(h[e-1])?h[e-1]:a,v=(a+M)*.5;s[1][e]=v,n[1][e]=a-v;for(let t=2;t<=8;t++){const r=1<<t-1,o=s[t-1][e];if(f>=t){const y=e-r>=0?s[t-1][e-r]:o,g=(o+(Number.isFinite(y)?y:o))*.5;s[t][e]=g,n[t][e]=o-g}else s[t][e]=o,n[t][e]=0}}const m=Math.pow(2,f),A=Math.log(m);let p=0;for(let e=0;e<l;e++){const a=n[1][e];if(p+=Math.abs(Number.isFinite(a)?a:0),e-m>=0){const o=n[1][e-m];p-=Math.abs(Number.isFinite(o)?o:0)}const t=p/m/.6745*Math.sqrt(2*A)*k;let r=s[f][e];for(let o=1;o<=8;o++)r+=F(n[o][e],t);b[e]=Number.isFinite(r)?r:NaN}return{wavelet:d(b)}}})}export{L as default};
